package org.opensourcepingpong.membership;
import java.util.*; import org.opensourcepingpong.common.api.BusinessException; import org.opensourcepingpong.organization.*; import org.springframework.http.HttpStatus; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class MembershipService { private final MembershipApplicationRepository apps;private final MembershipRepository memberships;private final RatingAccountRepository accounts;private final RatingLedgerRepository ledgers;private final AuthorizationService auth;private final OrganizationRoleRepository roles;private final UserOrganizationRoleRepository userRoles;private final JdbcTemplate jdbc;
 public MembershipService(MembershipApplicationRepository apps,MembershipRepository memberships,RatingAccountRepository accounts,RatingLedgerRepository ledgers,AuthorizationService auth,OrganizationRoleRepository roles,UserOrganizationRoleRepository userRoles,JdbcTemplate jdbc){this.apps=apps;this.memberships=memberships;this.accounts=accounts;this.ledgers=ledgers;this.auth=auth;this.roles=roles;this.userRoles=userRoles;this.jdbc=jdbc;}
 @Transactional public ApplicationView apply(UUID user,ApplyRequest r){if(memberships.existsByUserId(user))throw new BusinessException(HttpStatus.CONFLICT,"MEMBERSHIP_ALREADY_ACTIVE","已是正式成员");if(apps.existsByUserIdAndStatus(user,ApplicationStatus.PENDING))throw new BusinessException(HttpStatus.CONFLICT,"MEMBERSHIP_APPLICATION_EXISTS","已有待审核申请");return view(apps.save(new MembershipApplication(user,r.realName(),r.studentNumber(),r.college(),r.major(),r.grade(),r.phone(),r.reason())));}
 public ApplicationView mine(UUID user){return apps.findAll().stream().filter(a->a.getUserId().equals(user)).max(Comparator.comparing(MembershipApplication::getId)).map(this::view).orElseThrow(()->new BusinessException(HttpStatus.NOT_FOUND,"MEMBERSHIP_APPLICATION_NOT_FOUND","暂无申请"));}
 public List<ApplicationView> pending(UUID user){auth.require(user,Permission.MEMBERSHIP_REVIEW);return apps.findByStatusOrderByCreatedAtAsc(ApplicationStatus.PENDING).stream().map(this::view).toList();}
 @Transactional public void review(UUID reviewer,UUID id,boolean approve,String comment){auth.require(reviewer,Permission.MEMBERSHIP_REVIEW);MembershipApplication app=apps.findById(id).orElseThrow(()->new BusinessException(HttpStatus.NOT_FOUND,"MEMBERSHIP_APPLICATION_NOT_FOUND","申请不存在"));if(app.getStatus()!=ApplicationStatus.PENDING)throw new BusinessException(HttpStatus.CONFLICT,"MEMBERSHIP_APPLICATION_ALREADY_REVIEWED","申请已审核");app.review(reviewer,approve,comment);if(approve){Membership m=memberships.save(new Membership(app.getUserId(),"OSC-"+UUID.randomUUID().toString().substring(0,8).toUpperCase()));accounts.save(new RatingAccount(app.getUserId()));ledgers.save(RatingLedger.initial(app.getUserId()));OrganizationRole member=roles.findByCode(RoleCode.MEMBER).orElseThrow();userRoles.save(new UserOrganizationRole(app.getUserId(),member.getId(),reviewer));}createReviewNotification(app.getUserId(),approve,comment);}
 private void createReviewNotification(UUID user,boolean approved,String comment){String title=approved?"入会申请已通过":"入会申请未通过";String content=comment==null||comment.isBlank()?title:title+"："+comment;jdbc.update("insert into notifications(id,user_id,notification_type,title,content) values(?,?,?,?,?)",UUID.randomUUID(),user,"MEMBERSHIP_REVIEW",title,content);}
 private ApplicationView view(MembershipApplication a){return new ApplicationView(a.getId(),a.getUserId(),a.getStatus().name(),a.getRealName());}
 public record ApplyRequest(@jakarta.validation.constraints.NotBlank @jakarta.validation.constraints.Size(max=40) String realName,@jakarta.validation.constraints.NotBlank @jakarta.validation.constraints.Size(max=40) String studentNumber,@jakarta.validation.constraints.NotBlank @jakarta.validation.constraints.Size(max=100) String college,@jakarta.validation.constraints.NotBlank @jakarta.validation.constraints.Size(max=100) String major,@jakarta.validation.constraints.NotBlank @jakarta.validation.constraints.Size(max=40) String grade,@jakarta.validation.constraints.NotBlank @jakarta.validation.constraints.Size(max=30) String phone,@jakarta.validation.constraints.Size(max=500) String reason){} public record ApplicationView(UUID id,UUID userId,String status,String realName){}
}
